def main() -> None:
    out = sys.argv[1] if len(sys.argv) > 1 else "/output/entry.png"
    parent = os.path.dirname(out)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(out, "wb") as f:
        f.write(base64.b64decode(_IMAGE_B64))


if __name__ == "__main__":
    main()
